beforeLengthFix:
{
        let p = <number>pin;
        if (!neopixelStrips[p]) {
            switch (pin) {
                case EZMakerDigitalPin.P8:
                    neopixelStrips[p] = neopixel.create(DigitalPin.P8, <number>type, NeoPixelMode.RGB);
                    break;
                case EZMakerDigitalPin.P12:
                    neopixelStrips[p] = neopixel.create(DigitalPin.P12, <number>type, NeoPixelMode.RGB);
                    break;
                case EZMakerDigitalPin.P13:
                    neopixelStrips[p] = neopixel.create(DigitalPin.P13, <number>type, NeoPixelMode.RGB);
                    break;
                case EZMakerDigitalPin.P16:
                    neopixelStrips[p] = neopixel.create(DigitalPin.P16, <number>type, NeoPixelMode.RGB);
                    break;
                default:
                    neopixelStrips[p] = neopixel.create(DigitalPin.P8, <number>type, NeoPixelMode.RGB);
            }
        }
        return neopixelStrips[p];
    }

beforeV1SenderFix:
{
        let p = <number>pin;
        if (!neopixelStrips[p] || neopixelStrips[p].length() !== <number>type) {
            let brightness = 128;
            if (neopixelStrips[p]) {
                brightness = neopixelStrips[p].brightness;
                // Send a full-length black frame before shrinking. Otherwise
                // LEDs beyond the new length retain their previous colors.
                neopixelStrips[p].clear();
                neopixelStrips[p].show();
            }
            switch (pin) {
                case EZMakerDigitalPin.P8:
                    neopixelStrips[p] = neopixel.create(DigitalPin.P8, <number>type, NeoPixelMode.RGB);
                    break;
                case EZMakerDigitalPin.P12:
                    neopixelStrips[p] = neopixel.create(DigitalPin.P12, <number>type, NeoPixelMode.RGB);
                    break;
                case EZMakerDigitalPin.P13:
                    neopixelStrips[p] = neopixel.create(DigitalPin.P13, <number>type, NeoPixelMode.RGB);
                    break;
                case EZMakerDigitalPin.P16:
                    neopixelStrips[p] = neopixel.create(DigitalPin.P16, <number>type, NeoPixelMode.RGB);
                    break;
                default:
                    neopixelStrips[p] = neopixel.create(DigitalPin.P8, <number>type, NeoPixelMode.RGB);
            }
            neopixelStrips[p].setBrightness(brightness);
        }
        return neopixelStrips[p];
    }
